import type { Metadata } from "next";
import { site, team } from "./site";

/** Describes what the shared OG image actually shows (its headline), for screen readers and link previews. */
export const OG_IMAGE_ALT = `${site.name} — Bring a national-level hackathon to your campus`;

/** Generated by app/opengraph-image.tsx. Set explicitly because a page's own
 * `openGraph` object replaces the inherited file-based image. */
export const ogImage = { url: "/opengraph-image", width: 1200, height: 630, alt: OG_IMAGE_ALT };

/** One public page: drives both its <head> metadata and its JSON-LD. */
export type PageSeo = {
  /** Page title. Gets " | Dev Syndicate" appended unless `absoluteTitle`. */
  title: string;
  description: string;
  /** Canonical path, e.g. "/services". */
  path: string;
  absoluteTitle?: boolean;
  /** Short name for the breadcrumb trail (defaults to `title`). */
  breadcrumb?: string;
};

const fullTitle = (p: PageSeo) => (p.absoluteTitle ? p.title : `${p.title} | ${site.name}`);
const abs = (path: string) => `${site.url}${path === "/" ? "" : path}`;

export function pageMetadata(page: PageSeo): Metadata {
  const title = fullTitle(page);
  return {
    title: page.absoluteTitle ? { absolute: page.title } : page.title,
    description: page.description,
    alternates: { canonical: page.path },
    openGraph: {
      title,
      description: page.description,
      url: page.path,
      siteName: site.name,
      type: "website",
      locale: "en_IN",
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description: page.description,
      images: [ogImage.url],
    },
  };
}

const ids = {
  organization: `${site.url}/#organization`,
  website: `${site.url}/#website`,
};

/**
 * Organization + WebSite, rendered on every public page. Only verified facts:
 * name, logo, contact details, city, and the founders' LinkedIn profiles.
 */
export function siteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": ids.organization,
        name: site.name,
        url: site.url,
        logo: { "@type": "ImageObject", url: `${site.url}/icon.png`, width: 512, height: 512 },
        description: site.description,
        email: site.email,
        telephone: site.phone.e164,
        address: {
          "@type": "PostalAddress",
          addressLocality: site.location.city,
          addressRegion: site.location.region,
          addressCountry: site.location.countryCode,
        },
        areaServed: { "@type": "Country", name: site.location.country },
        founder: team.map((p) => ({ "@type": "Person", name: p.name, jobTitle: p.role, sameAs: [p.linkedin] })),
        contactPoint: {
          "@type": "ContactPoint",
          contactType: "sales",
          name: site.primaryContact.name,
          telephone: site.primaryContact.phone.e164,
          email: site.email,
          areaServed: site.location.countryCode,
          availableLanguage: ["en"],
        },
      },
      {
        "@type": "WebSite",
        "@id": ids.website,
        url: site.url,
        name: site.name,
        description: site.description,
        inLanguage: "en-IN",
        publisher: { "@id": ids.organization },
      },
    ],
  };
}

/** WebPage, plus a BreadcrumbList for pages below the homepage. */
export function pageJsonLd(page: PageSeo) {
  const url = abs(page.path);
  const isHome = page.path === "/";
  const webPage = {
    "@type": page.path === "/about" ? "AboutPage" : page.path === "/contact" ? "ContactPage" : "WebPage",
    "@id": `${url}#webpage`,
    url,
    name: fullTitle(page),
    description: page.description,
    inLanguage: "en-IN",
    isPartOf: { "@id": ids.website },
    about: { "@id": ids.organization },
    ...(isHome ? {} : { breadcrumb: { "@id": `${url}#breadcrumb` } }),
  };
  const breadcrumb = {
    "@type": "BreadcrumbList",
    "@id": `${url}#breadcrumb`,
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: site.url },
      { "@type": "ListItem", position: 2, name: page.breadcrumb ?? page.title, item: url },
    ],
  };
  return { "@context": "https://schema.org", "@graph": isHome ? [webPage] : [webPage, breadcrumb] };
}

/** Serialises JSON-LD safely for inline <script> tags. */
export function jsonLd(data: unknown) {
  return { __html: JSON.stringify(data).replace(/</g, "\\u003c") };
}
